void setup_terminal(int tty_fd) {
    struct termios oldt, newt;

    tcgetattr(tty_fd, &oldt);
    newt = oldt;

    /* Raw mode */
    newt.c_lflag &= ~(ECHO | ICANON);
    newt.c_iflag &= ~(IXON);
    newt.c_oflag &= 0;
    newt.c_cflag &= ~(CSIZE | PARENB);
    newt.c_cflag |= CS8;
    newt.c_cc[VMIN] = 0;
    newt.c_cc[VTIME] = 0;

    tcsetattr(tty_fd, TCSANOW, &newt);

    /* Save old terminal settings */
    g_old_style = 1;
}

void restore_terminal(void) {
    if (g_old_style) {
        tcsetattr(STDIN_FILENO, TCSANOW, &g_old_termios);
    }
}

void set_terminal_size(void) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
        g_term_width = ws.ws_col;
        g_term_height = ws.ws_row;
    } else {
        g_term_width = 80;
        g_term_height = 24;
    }
}

void set_color(int color) {
    switch (color) {
        case COLOR_GREEN: g_color_attr = 1; break;
        case COLOR_RED: g_color_attr = 31; break;
        case COLOR_BLUE: g_color_attr = 34; break;
        case COLOR_WHITE: g_color_attr = 37; break;
        case COLOR_YELLOW: g_color_attr = 33; break;
        case COLOR_CYAN: g_color_attr = 36; break;
        case COLOR_MAGENTA: g_color_attr = 35; break;
        case COLOR_BLACK: g_color_attr = 30; break;
    }
}

void set_bold(int bold) {
    if (bold) {
        g_color_attr |= 1;
    } else {
        g_color_attr &= ~1;
    }
}

void print_matrix_line(int width) {
    int i, char_idx = 0;

    for (i = 0; i < width; i++) {
        if (g_rainbow) {
            int r = (i + char_idx * 10) % 256;
            int g = (i + char_idx * 10 + 85) % 256;
            int b = (i + char_idx * 10 + 170) % 256;
            printf("\033[%d;%d;%dm", r, g, b);
        } else if (g_color_attr) {
            printf("\033[%dm", g_color_attr);
        }

        if (g_all_bold) {
            printf("\033[1m");
        } else if (g_bold) {
            printf("\033[1m");
        } else if (g_no_bold) {
            printf("\033[0m");
        }

        if (g_japanese) {
            printf("%c", 0x30A2 + (char_idx % 20));
        } else if (g_lambda) {
            printf("λ");
        } else {
            printf("%c", g_matrix_chars[char_idx % (sizeof(g_matrix_chars) - 1)]);
        }

        char_idx++;
    }

    if (g_color_attr) {
        printf("\033[0m");
    }
    if (g_all_bold || g_bold) {
        printf("\033[0m");
    }
}

void print_message(const char *msg) {
    int msg_len = strlen(msg);
    int padding = (g_term_width - msg_len) / 2;

    for (int i = 0; i < padding; i++) {
        printf(" ");
    }
    printf("%s\n", msg);
    for (int i = 0; i < padding; i++) {
        printf(" ");
    }
}
