int main(int argc, char **argv) {
    int flags = 0;
    int delay = DEFAULT_DELAY;
    char *color = NULL;
    char *message = NULL;
    char *tty = NULL;
    int tty_fd = STDIN_FILENO;
    fd_set readfds;
    struct timeval tv;
    int i;

    /* Parse options */
    if (parse_options(argc, argv, &flags, &delay, &color, &message, &tty) != 0) {
        return 1;
    }

    /* Set global state */
    g_flags = flags;
    g_delay = delay;
    if (color) {
        g_color = validate_color(color);
    }
    if (message) {
        g_message = message;
    }
    if (tty) {
        tty_fd = open(tty, O_RDWR);
        if (tty_fd < 0) {
            tty_fd = STDIN_FILENO;
        }
    }

    /* Setup terminal */
    set_terminal_size();
    setup_signals();

    if (tty_fd != STDIN_FILENO) {
        setup_terminal(tty_fd);
        tcgetattr(tty_fd, &g_old_termios);
    }

    /* Set color and bold */
    set_color(g_color);
    if (flags & OPT_BOLD) {
        g_bold = 1;
    }
    if (flags & OPT_ALL_BOLD) {
        g_all_bold = 1;
        g_bold = 0;
    }
    if (flags & OPT_NO_BOLD) {
        g_no_bold = 1;
    }

    /* Print message if provided */
    if (g_message) {
        print_message(g_message);
    }

    /* Main loop */
    while (g_running && !g_quit) {
        /* Clear screen */
        printf("\033[2J\033[H");

        /* Print message again if present */
        if (g_message) {
            print_message(g_message);
        }

        /* Print matrix lines */
        for (i = 0; i < g_term_height; i++) {
            print_matrix_line(g_term_width);
            printf("\n");
        }

        /* Update delay */
        tv.tv_sec = 0;
        tv.tv_usec = delay * 100000;

        /* Wait for input or timeout */
        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);
        select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv);

        /* Check for input */
        if (FD_ISSET(STDIN_FILENO, &readfds)) {
            char buf[10];
            int n = read(STDIN_FILENO, buf, sizeof(buf) - 1);
            if (n > 0) {
                buf[n] = '\0';
                /* Handle keystrokes */
                if (buf[0] == 'q') {
                    g_quit = 1;
                } else if (buf[0] == 'a') {
                    g_async = !g_async;
                } else if (buf[0] == 'b') {
                    g_bold = !g_bold;
                } else if (buf[0] == 'B') {
                    g_all_bold = 1;
                    g_bold = 0;
                } else if (buf[0] == 'n') {
                    g_no_bold = 1;
                    g_bold = 0;
                    g_all_bold = 0;
                } else if (buf[0] >= '0' && buf[0] <= '9') {
                    delay = (buf[0] - '0') * 10;
                }
            }
        }

        /* Check savescreen mode */
        if (g_savescreen && !g_async) {
            /* Wait for keystroke */
            FD_ZERO(&readfds);
            FD_SET(STDIN_FILENO, &readfds);
            select(STDIN_FILENO + 1, &readfds, NULL, NULL, NULL);
            g_quit = 1;
        }
    }

    /* Restore terminal */
    restore_terminal();

    return 0;
}
